    cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    priority_queue<long long, vector<long long>, greater<long long>> heap;
    for (long long x : a) {
        heap.push(x);
        if ((long long)heap.size() > k) heap.pop();
        if ((long long)heap.size() == k) cout << heap.top() << "\n";
